-- Ported from Anatomist dff2e395 StagingSchema; temporary, unpublished records.
CREATE TABLE stage_nodes(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,symbol_id TEXT,domain TEXT,language TEXT,provider_id TEXT,entity_kind TEXT,language_kind TEXT,label TEXT,kind TEXT,qualified_name TEXT,package TEXT,namespace TEXT,source_file TEXT,source_location TEXT,begin_line INTEGER,begin_column INTEGER,end_line INTEGER,end_column INTEGER,source_ordinal INTEGER,module TEXT,scope TEXT,metadata TEXT,arity_key TEXT,producer_id TEXT NOT NULL,fact_hash BLOB);
CREATE TRIGGER stage_node_owner_conflict BEFORE UPDATE ON stage_nodes WHEN old.producer_id<>new.producer_id BEGIN SELECT RAISE(ABORT,'EXTENSION_NODE_OWNERSHIP_CONFLICT'); END;
CREATE INDEX stage_nodes_symbol ON stage_nodes(symbol_id);
CREATE INDEX stage_nodes_candidate ON stage_nodes(symbol_id,source_file,module,scope);
CREATE INDEX stage_nodes_arity ON stage_nodes(arity_key);
CREATE TABLE stage_declarations(seq INTEGER PRIMARY KEY AUTOINCREMENT,symbol_id TEXT NOT NULL,domain TEXT,language TEXT,provider_id TEXT,entity_kind TEXT,language_kind TEXT,qualified_name TEXT NOT NULL,label TEXT NOT NULL,kind TEXT NOT NULL,declaration_kind TEXT NOT NULL,type_kind TEXT,visibility TEXT NOT NULL,modifiers TEXT NOT NULL,declared_modifiers TEXT NOT NULL,implicit_modifiers TEXT NOT NULL,declaring_type TEXT,namespace TEXT,source_file TEXT NOT NULL,source_location TEXT,begin_line INTEGER,begin_column INTEGER,end_line INTEGER,end_column INTEGER,module TEXT NOT NULL,scope TEXT NOT NULL,nesting_depth INTEGER NOT NULL,direct_member INTEGER NOT NULL,synthetic INTEGER NOT NULL,binding_resolved INTEGER NOT NULL,producer_id TEXT NOT NULL,UNIQUE(provider_id,symbol_id,module,scope,source_file,producer_id));
CREATE TABLE stage_edges(seq INTEGER PRIMARY KEY AUTOINCREMENT,source_ref TEXT,target_ref TEXT,external_target_fqn TEXT,external_target_symbol TEXT,external_target_language TEXT,external_target_provider_id TEXT,relation TEXT,semantic TEXT,mechanism TEXT,language TEXT,provider_id TEXT,call_kind TEXT,confidence TEXT,resolution TEXT,context TEXT,is_external INTEGER,source_file TEXT,source_location TEXT,begin_line INTEGER,begin_column INTEGER,end_line INTEGER,end_column INTEGER,source_ordinal INTEGER,syntax_target TEXT,receiver_static_type TEXT,metadata TEXT,source_module TEXT,source_scope TEXT,source_is_key INTEGER,target_is_key INTEGER,resolved_source TEXT,resolved_target TEXT,target_arity_key TEXT,producer_id TEXT NOT NULL,fact_hash BLOB,fact_ordinal INTEGER NOT NULL DEFAULT 0);
CREATE TABLE stage_call_sites(seq INTEGER PRIMARY KEY AUTOINCREMENT,source_ref TEXT,target_ref TEXT,external_target_fqn TEXT,external_target_symbol TEXT,external_target_language TEXT,external_target_provider_id TEXT,relation TEXT,semantic TEXT,mechanism TEXT,language TEXT,provider_id TEXT,call_kind TEXT,confidence TEXT,resolution TEXT,context TEXT,is_external INTEGER,source_file TEXT,source_location TEXT,begin_line INTEGER,begin_column INTEGER,end_line INTEGER,end_column INTEGER,source_ordinal INTEGER,syntax_target TEXT,receiver_static_type TEXT,metadata TEXT,source_module TEXT,source_scope TEXT,source_is_key INTEGER,target_is_key INTEGER,resolved_source TEXT,resolved_target TEXT,target_arity_key TEXT,producer_id TEXT NOT NULL,fact_hash BLOB,fact_ordinal INTEGER NOT NULL DEFAULT 0);
CREATE INDEX stage_edges_refs ON stage_edges(source_ref,target_ref,external_target_fqn);
CREATE TABLE stage_annotations(seq INTEGER PRIMARY KEY AUTOINCREMENT,node_ref TEXT,annotation_fqn TEXT,raw_name TEXT NOT NULL,attributes TEXT,target_kind TEXT NOT NULL,target_path TEXT,language TEXT NOT NULL,provider_id TEXT NOT NULL,mechanism TEXT NOT NULL,resolution_status TEXT NOT NULL,source_file TEXT,source_location TEXT,begin_line INTEGER,begin_column INTEGER,end_line INTEGER,end_column INTEGER,source_module TEXT,source_scope TEXT,node_is_key INTEGER,resolved_node TEXT,producer_id TEXT NOT NULL,fact_hash BLOB,fact_ordinal INTEGER NOT NULL DEFAULT 0);
CREATE INDEX stage_annotations_ref ON stage_annotations(node_ref);
CREATE TABLE stage_annotation_meta(seq INTEGER PRIMARY KEY AUTOINCREMENT,annotation_fqn TEXT NOT NULL,meta_annotation_fqn TEXT,raw_name TEXT NOT NULL,language TEXT NOT NULL,provider_id TEXT NOT NULL,mechanism TEXT NOT NULL,resolution_status TEXT NOT NULL,source_file TEXT,source_location TEXT,producer_id TEXT NOT NULL);
CREATE TABLE stage_semantic_annotations(seq INTEGER PRIMARY KEY AUTOINCREMENT,node_ref TEXT,category TEXT,business_label TEXT,business_description TEXT,domain_context TEXT,source TEXT,confidence TEXT,source_file TEXT,source_module TEXT,source_scope TEXT,node_is_key INTEGER,resolved_node TEXT,producer_id TEXT NOT NULL);
CREATE INDEX stage_semantic_ref ON stage_semantic_annotations(node_ref);
